  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: size
  }
});
var tabList = [source.key + "/tvb/", source.key + "/tnt/"];
java.ajaxAll(tabList).forEach((response, index) => {
	let isTag = index == 0;
	push(isTag ? "分类" : "排行", null, 1);
org.jsoup.Jsoup.parse(response.body()).select('.class .container a').forEach(e => push(e.text(), String(e.attr('href')).replace(/\d+\/$/, "") + (isTag ? "{{page}}/" : "?page={{page}}"), 0.25))
});
JSON.stringify(result);

source.jsLib:
function decrypt(encryptedString) {
    const { java } = this
    let encryptedData_ = String(java.base64Decode(encryptedString));
    let controlNum = parseInt(encryptedData_.slice(8, 11));
    let text = encryptedData_.slice(controlNum + 11, encryptedData_.length - controlNum);
     let encryptedData = text.replace(/_/g, "8L3A+").replace(/-/g, "PHA+");
     return java.base64Decode(encryptedData);
}

